import numpy as np
import scipy.stats as st

@test
def test_censored_fit():
    cd = st.CensoredData(uncensored=[5.378106763587066, 3.954503117038505, 4.173872913216213, 0.11706523472028874, 4.349154326264351, 5.562421339595298, 3.892354327151895, 4.378886906681695, 4.342352191884075, 3.4157064892822033, 5.909916142481711, 4.801603896565224, 6.090577427929364, 3.785628600258726, 5.25365569422374, 3.215451913140419, 5.376070173961372, 5.661142016270652, 5.821007825940526, 2.978484999693331, 1.7231149935289496, 1.5411770656910369, 1.99033717227136, 5.257431314948137, 6.4448617446149985, 5.421143624750561, 5.568076290500741, 4.660479004553729, 2.7405680764384903, 4.1562823476433675, 5.485877706197471, 3.4710717685592014, 2.8418790817261153, 3.873425602991924, 4.529988986216348, 1.2549409647879521, 2.1626686203970302, 5.307163773071916, 5.175838084619045, 5.5478645091846595, 4.4392353721141244, 3.457895680360939], right=[6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5])
    p = st.fit_censored(st.norm, cd, [5.0, 1.5])
    e = [5.2802309198738335, 2.1629602186061008]
    assert abs(float(p[0]) - e[0]) < 1e-3
    assert abs(float(p[1]) - e[1]) < 1e-3
    assert len(cd) == 60 and cd.num_censored() == 18
